/**
 * SPEC-059 (AC-08..AC-16): vista de la ventana desacoplada del asistente —
 * solo el panel a ventana completa (sin sidebar, top bar ni el resto de
 * secciones del detalle), hidratada con el snapshot de main al abrir a mitad
 * de sesión, espejo de la cola en los dos sentidos y con las acciones inline
 * delegando en el bridge.
 * Generated by QA Dev agent.
 *
 * Frontera de mocking: bridge window.api (installMockApi). La página se monta
 * en su ruta real (DETACHED_ROUTES.assistant, el mismo módulo con el que main
 * construye el hash) bajo TooltipProvider — igual que en App.tsx, donde las
 * rutas /detached/* son hermanas del Layout y siguen bajo los providers.
 * El AssistantPanel es el REAL: los literales de cola vacía, pausa y error
 * salen por reutilización, que es justo lo que los ACs exigen (el panel no
 * puede divergir del de la página principal).
 */
import { act, render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { TooltipProvider } from '@/components/ui/tooltip'
import { AssistantWindowPage } from '@/pages/AssistantWindowPage'
import type { AssistantQueueItem, AssistantUpdateEvent } from '@/types/assistant'
import { DETACHED_ROUTES } from '@/types/detached'
import { installMockApi, type MockApiHandle } from '../../helpers/mockApi'

let mockApi: MockApiHandle

const QUESTION = '¿Cuándo fue la última vez que pasó?'
const REASON = 'Falta un caso concreto: pide el último episodio'
const PINNED_QUESTION = '¿Cómo lo resolvéis hoy?'
const EMPTY_MESSAGE = 'El asistente te sugerirá la siguiente pregunta en cuanto haya conversación.'

function queueItem(overrides: Partial<AssistantQueueItem> = {}): AssistantQueueItem {
  return {
    id: 'q-1',
    action: 'dig_deeper',
    suggestedQuestion: QUESTION,
    reason: REASON,
    alarms: ['generic'],
    ...overrides
  }
}

function event(overrides: Partial<AssistantUpdateEvent> = {}): AssistantUpdateEvent {
  return {
    state: 'active',
    queue: { pending: [queueItem()], pinned: [] },
    objectivesMet: [],
    ...overrides
  }
}

function renderAssistantWindow(): void {
  render(
    <TooltipProvider>
      <MemoryRouter initialEntries={['/detached/assistant/i-1']}>
        <Routes>
          <Route path={DETACHED_ROUTES.assistant} element={<AssistantWindowPage />} />
        </Routes>
      </MemoryRouter>
    </TooltipProvider>
  )
}

/** Inyecta un evento push del asistente (main → todas las ventanas). */
function push(value: AssistantUpdateEvent): void {
  act(() => {
    mockApi.emitAssistantUpdate(value)
  })
}

beforeEach(() => {
  vi.clearAllMocks()
  mockApi = installMockApi()
})

describe('AssistantWindowPage (ventana desacoplada del asistente, SPEC-059)', () => {
  // SPEC-059 · AC-08
  it('renders only the assistant panel, without sidebar, top bar or any other detail section', async () => {
    renderAssistantWindow()
    push(event())

    const root = await screen.findByTestId('assistant-window-root')
    expect(within(root).getByTestId('assistant-queue')).toBeInTheDocument()
    // Nada del chrome de la app ni del resto del detalle
    expect(screen.queryByRole('banner')).not.toBeInTheDocument()
    expect(screen.queryByRole('navigation')).not.toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Guión' })).not.toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Objetivos' })).not.toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Nota' })).not.toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Iniciar grabación' })).not.toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Detener' })).not.toBeInTheDocument()
    expect(screen.queryByTestId('assistant-live-section')).not.toBeInTheDocument()
  })

  // SPEC-059 · AC-09
  it('hydrates the current queue from the main snapshot without waiting for the next analysis', async () => {
    vi.mocked(mockApi.api.assistant.getSnapshot).mockResolvedValue(
      event({
        queue: {
          pending: [queueItem()],
          pinned: [queueItem({ id: 'q-2', suggestedQuestion: PINNED_QUESTION })]
        }
      })
    )

    renderAssistantWindow()

    // Sin un solo evento push: la cola llega por la consulta puntual
    expect(await screen.findByText(QUESTION)).toBeInTheDocument()
    expect(await screen.findByTestId('assistant-pinned-section')).toBeInTheDocument()
    expect(vi.mocked(mockApi.api.assistant.getSnapshot)).toHaveBeenCalledTimes(1)
  })

  // SPEC-059 · AC-09 (la hidratación tardía jamás pisa un estado más nuevo)
  it('keeps the pushed state when the snapshot resolves late with an older queue', async () => {
    let resolveSnapshot: (value: AssistantUpdateEvent | null) => void = () => undefined
    vi.mocked(mockApi.api.assistant.getSnapshot).mockReturnValue(
      new Promise<AssistantUpdateEvent | null>((resolve) => {
        resolveSnapshot = resolve
      })
    )
    renderAssistantWindow()

    // Llega un evento push mientras el snapshot sigue en vuelo…
    push(
      event({
        queue: { pending: [queueItem({ id: 'q-9', suggestedQuestion: QUESTION })], pinned: [] }
      })
    )
    expect(await screen.findByText(QUESTION)).toBeInTheDocument()

    // …y el snapshot resuelve DESPUÉS con la cola anterior (más vieja)
    await act(async () => {
      resolveSnapshot(
        event({
          queue: {
            pending: [queueItem({ id: 'q-0', suggestedQuestion: 'Pregunta vieja' })],
            pinned: []
          }
        })
      )
    })

    expect(screen.getByText(QUESTION)).toBeInTheDocument()
    expect(screen.queryByText('Pregunta vieja')).not.toBeInTheDocument()
  })

  // SPEC-059 · AC-10
  it('renders each queued item with its action badge, alarm chips, question, reason and inline actions', async () => {
    renderAssistantWindow()
    push(
      event({
        queue: {
          pending: [queueItem()],
          pinned: [queueItem({ id: 'q-2', suggestedQuestion: PINNED_QUESTION, alarms: [] })]
        }
      })
    )

    const item = await screen.findByTestId('assistant-queue-item')
    expect(within(item).getByText('Profundiza')).toBeInTheDocument()
    expect(within(item).getByText('Genérico')).toBeInTheDocument()
    expect(within(item).getByText(QUESTION)).toBeInTheDocument()
    expect(within(item).getByText(REASON)).toBeInTheDocument()
    expect(within(item).getByTestId('assistant-item-answered')).toBeInTheDocument()
    expect(within(item).getByTestId('assistant-item-discard')).toBeInTheDocument()
    expect(within(item).getByRole('button', { name: 'Anclar pregunta' })).toBeInTheDocument()
    // Sección «Ancladas» idéntica a la de la página principal
    const pinned = screen.getByTestId('assistant-pinned-section')
    expect(within(pinned).getByText('Ancladas')).toBeInTheDocument()
    expect(within(pinned).getByText(PINNED_QUESTION)).toBeInTheDocument()
  })

  // SPEC-059 · AC-11
  it('shows a question added by the assistant without any user interaction', async () => {
    renderAssistantWindow()
    push(event({ state: 'idle', queue: { pending: [], pinned: [] } }))
    expect(await screen.findByText(EMPTY_MESSAGE)).toBeInTheDocument()

    push(event())

    expect(await screen.findByText(QUESTION)).toBeInTheDocument()
    expect(screen.queryByText(EMPTY_MESSAGE)).not.toBeInTheDocument()
  })

  // SPEC-059 · AC-12
  it('delegates the inline queue actions to the same bridge methods as the main page', async () => {
    const user = userEvent.setup()
    renderAssistantWindow()
    push(event())
    const item = await screen.findByTestId('assistant-queue-item')

    await user.click(within(item).getByTestId('assistant-item-discard'))
    await user.click(within(item).getByTestId('assistant-item-answered'))
    await user.click(within(item).getByRole('button', { name: 'Anclar pregunta' }))

    expect(vi.mocked(mockApi.api.assistant.resolveItem)).toHaveBeenCalledWith('q-1', 'discarded')
    expect(vi.mocked(mockApi.api.assistant.resolveItem)).toHaveBeenCalledWith('q-1', 'answered')
    expect(vi.mocked(mockApi.api.assistant.setPinned)).toHaveBeenCalledWith('q-1', true)
  })

  // SPEC-059 · AC-13 (la cola que main re-emite tras resolver/anclar en la
  // página principal llega a esta ventana como cualquier otro evento)
  it('reflects the queue re-emitted by main after the question is resolved from the main page', async () => {
    renderAssistantWindow()
    push(event())
    expect(await screen.findByText(QUESTION)).toBeInTheDocument()

    // main resuelve la pregunta desde la otra superficie y re-emite la cola
    push(event({ queue: { pending: [], pinned: [] } }))

    await waitFor(() => expect(screen.queryByText(QUESTION)).not.toBeInTheDocument())
    expect(screen.getByText(EMPTY_MESSAGE)).toBeInTheDocument()
  })

  // SPEC-059 · AC-14
  it('shows the empty queue message with its literal copy', async () => {
    renderAssistantWindow()

    const root = await screen.findByTestId('assistant-window-root')
    expect(within(root).getByText(EMPTY_MESSAGE)).toBeInTheDocument()
    expect(screen.queryByTestId('assistant-queue')).not.toBeInTheDocument()
  })

  // SPEC-059 · AC-15
  it('shows the cost pause notice and resumes the assistant from this window', async () => {
    const user = userEvent.setup()
    renderAssistantWindow()
    push(
      event({ state: 'paused', queue: { pending: [queueItem()], pinned: [] }, pauseLimitUsd: 2 })
    )

    const alert = await screen.findByTestId('assistant-paused-alert')
    expect(within(alert).getByText(/Límite de coste alcanzado \(\$2\.00\)/)).toBeInTheDocument()
    await user.click(within(alert).getByRole('button', { name: 'Reanudar asistente' }))

    expect(vi.mocked(mockApi.api.assistant.resume)).toHaveBeenCalledTimes(1)
  })

  // SPEC-059 · AC-16
  it('shows the discreet failure line without hiding the queue', async () => {
    renderAssistantWindow()
    push(
      event({
        state: 'error',
        error: { kind: 'connection', message: 'Fallo de red' }
      })
    )

    expect(
      await screen.findByText('No se pudo analizar (se reintentará): Fallo de red')
    ).toBeInTheDocument()
    // La cola sigue visible bajo la línea de error
    expect(screen.getByText(QUESTION)).toBeInTheDocument()
  })
})
